  ('tpl-gpu', 1, 'gpu', '[{"id":"gpu-1","section":"Ground power unit","text":"Cables, plug and pins free of cuts, burns or bent pins","critical":true,"naAllowed":false},{"id":"gpu-2","section":"Ground power unit","text":"Output voltage within limits","critical":true,"naAllowed":false,"reading":{"unit":"V AC","min":112,"max":118}},{"id":"gpu-3","section":"Ground power unit","text":"Output frequency within limits","critical":true,"naAllowed":false,"reading":{"unit":"Hz","min":395,"max":405}},{"id":"gpu-4","section":"Ground power unit","text":"Emergency stop works","critical":true,"naAllowed":false},{"id":"gpu-5","section":"Ground power unit","text":"No fuel, oil or coolant leaks","critical":true,"naAllowed":false},{"id":"gpu-6","section":"Ground power unit","text":"Fuel and engine oil levels correct","critical":false,"naAllowed":false},{"id":"gpu-7","section":"Ground power unit","text":"Cable stowage and earthing strap in place","critical":false,"naAllowed":false},{"id":"gpu-8","section":"Ground power unit","text":"Warning lights and gauges working","critical":false,"naAllowed":false},{"id":"gpu-9","section":"Ground power unit","text":"Tow eye, drawbar and parking brake serviceable","critical":true,"naAllowed":false}]'::jsonb, true, now()),
